// Embed assets/ (favicons, logos, fonts) into src/brandAssets.ts.
//
//   npm run brand:assets
//
// The service is one Vercel function behind a catch-all rewrite, so it serves
// its own favicon, logos and fonts from memory rather than relying on a static
// output directory. Re-run after changing anything in assets/; the test suite
// fails if the generated file is stale.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const root = new URL('../', import.meta.url);
const read = (p) => readFileSync(new URL(`assets/${p}`, root));

/** URL path → [file under assets/, content type]. Favicons live at the root,
 *  where browsers and the web manifest look for them. */
const FILES = {
  '/favicon.ico': ['favicon.ico', 'image/x-icon'],
  '/favicon-16x16.png': ['favicon-16x16.png', 'image/png'],
  '/favicon-32x32.png': ['favicon-32x32.png', 'image/png'],
  '/apple-touch-icon.png': ['apple-touch-icon.png', 'image/png'],
  '/android-chrome-192x192.png': ['android-chrome-192x192.png', 'image/png'],
  '/android-chrome-512x512.png': ['android-chrome-512x512.png', 'image/png'],
  '/brand/logo-on-light.webp': ['logo-on-light.webp', 'image/webp'],
  '/brand/logo-on-dark.webp': ['logo-on-dark.webp', 'image/webp'],
  '/brand/fonts/inter-latin-var.woff2': ['fonts/inter-latin-var.woff2', 'font/woff2'],
  '/brand/fonts/poppins-latin-600-normal.woff2': ['fonts/poppins-latin-600-normal.woff2', 'font/woff2'],
  '/brand/fonts/poppins-latin-700-normal.woff2': ['fonts/poppins-latin-700-normal.woff2', 'font/woff2']
};

const manifest = JSON.stringify({
  name: 'ATMT Labs',
  short_name: 'ATMT Labs',
  icons: [
    { src: '/android-chrome-192x192.png', sizes: '192x192', type: 'image/png' },
    { src: '/android-chrome-512x512.png', sizes: '512x512', type: 'image/png' }
  ],
  theme_color: '#ffffff',
  background_color: '#ffffff',
  display: 'standalone'
});

export function render() {
  const lines = Object.entries(FILES).map(([path, [file, type]]) =>
    `  ${JSON.stringify(path)}: { type: ${JSON.stringify(type)}, b64: ${JSON.stringify(read(file).toString('base64'))} },`);
  lines.push(`  "/site.webmanifest": { type: "application/manifest+json", b64: ${JSON.stringify(Buffer.from(manifest).toString('base64'))} },`);
  return `// GENERATED by scripts/brand-assets.mjs from assets/. Do not edit; run \`npm run brand:assets\`.
// Fonts: SIL OFL 1.1, see assets/fonts/LICENSE.txt.
export const BRAND_ASSETS: Record<string, { type: string; b64: string }> = {
${lines.join('\n')}
};
`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(new URL('src/brandAssets.ts', root), render());
  console.log(`Wrote src/brandAssets.ts (${Object.keys(FILES).length + 1} files).`);
}
